 private static final Map<Integer,Map<String,NervRigidMeshSweepR52>> BASE=new HashMap<>();
 public static UUID proposedIdentityR52(long epoch,UUID eva){return UUID.nameUUIDFromBytes(("projectseele:r52:original-carrier:"+epoch+":"+eva).getBytes(StandardCharsets.UTF_8));}
 private static CompoundTag encode(RigidTransform f){return NervAircraftFrameR52.encodeRigid(f);}
 private static RigidTransform decode(CompoundTag t){return NervAircraftFrameR52.decodeRigid(t);}
 public static boolean declared(NervCarrierPlatformEntity e){var t=e.originalCarrierStateR52();return t.getString("Source").equals(SOURCE_SHA)&&t.getString("GuideSource").equals(NervFootGuideRigR52.SOURCE_SHA)&&t.hasUUID("OriginalEva")&&t.getLong("Epoch")>0;}
 public static UUID entityUUID(EvaUnit01Entity e){return EvaMechanicalFrameR52.originalCarrierUUIDR52(e);}
 public static NervCarrierPlatformEntity controller(ServerLevel l,Original o){var actor=l.getEntity(proposedIdentityR52(o.epoch(),o.eva()));return actor instanceof NervCarrierPlatformEntity n&&declared(n)&&n.getUnitVariant()==o.variant()&&n.originalCarrierStateR52().getUUID("OriginalEva").equals(o.eva())?n:null;}
 /** Read the fixed bay hardware's stored clock, including on clients. The
  * original carrier may currently be at a different exit or unloaded. */
 public static NervLegacyCarrierRideR52.LeadSampleR52 actualLeadSampleR52(NervCarrierPlatformEntity gantry,float partial){if(!gantry.isRestraintGantry()||!gantry.hasDeclaredMachineFrameR52()||gantry.getPersistentData().getLong("MachineEpochR52")<=0&&!gantry.level().isClientSide)return null;var spec=gantry.declaredServiceFootDriveR52();float rise=gantry.serviceLeadRiseR52(partial),bridge=gantry.serviceGuideBridgeR52(partial);long at=gantry.serviceLeadAtR52();if(spec==null||spec.variant()!=gantry.getUnitVariant()||!Float.isFinite(rise+bridge)||at==Long.MIN_VALUE)return null;return new NervLegacyCarrierRideR52.LeadSampleR52(spec,bridge,rise,at);}
 /** Only the paired source proof may advance a fixed bay's lift sample. */
 public static final class DeclaredLeadState {
  private final UUID actor;private final CompoundTag before,after;private final NervLegacyCarrierRideR52.AcceptedLeadStep proof;
  private DeclaredLeadState(NervCarrierPlatformEntity e,NervLegacyCarrierRideR52.AcceptedLeadStep proof,CompoundTag after){actor=e.getUUID();before=e.serviceLeadStateR52();this.after=after.copy();this.proof=proof;}
  public CompoundTag next(){return after.copy();}
  public boolean current(NervCarrierPlatformEntity e){return e.level() instanceof ServerLevel l&&actor.equals(e.getUUID())&&e.serviceLeadStateR52().equals(before)&&proof.current(l);}
 }
 public static boolean acceptLeadStepR52(ServerLevel l,NervLegacyCarrierRideR52.AcceptedLeadStep proof){if(proof==null||!proof.current(l)||!(l.getEntity(proof.gantry()) instanceof NervCarrierPlatformEntity g)||!(l.getEntity(proof.carrier()) instanceof NervCarrierPlatformEntity c)||!declared(c)||!Objects.equals(g.declaredServiceFootDriveR52(),proof.toSample().spec())||!NervAirTransportManifestR52.same(actualRoot(c,1),proof.toSample().spec().bay())||progress(c,1)!=proof.toSample().rise()||g.getPersistentData().getLong("MachineEpochR52")!=c.originalCarrierStateR52().getLong("Epoch")||!g.getPersistentData().getString("MachineDirectoryR52").equals(c.originalCarrierStateR52().getString("Directory")))return false;var tag=g.serviceLeadStateR52();tag.putFloat("PreviousLeadRise",proof.fromSample().rise());tag.putFloat("LeadRise",proof.toSample().rise());tag.putLong("LeadAt",proof.checkedAt());g.acceptServiceLeadStateR52(new DeclaredLeadState(g,proof,tag));return true;}
 public static FootSupportFrameR52.Binding nominalBinding(int variant)throws IOException {return NervFootGuideRigR52.nominalBinding(variant);}
 public static float progress(NervCarrierPlatformEntity e,float partial){var t=e.originalCarrierStateR52();if(!declared(e))return Float.NaN;return e.level().isClientSide?net.minecraft.util.Mth.lerp((float)net.minecraft.util.Mth.clamp(e.level().getGameTime()-t.getLong("At")+(double)partial,0,1),t.getFloat("PreviousRise"),t.getFloat("Rise")):t.getFloat("Rise");}
 public static RigidTransform actualRoot(NervCarrierPlatformEntity e,float partial){var t=e.originalCarrierStateR52();if(!declared(e))throw new IllegalStateException("Original carrier source/controller required");var current=decode(t.getCompound("Current"));if(!e.level().isClientSide)return current;var eva=continuousEvaR52(e);if(eva!=null)return EvaMechanicalFrameR52.frame(eva,partial);double clock=net.minecraft.util.Mth.clamp(e.level().getGameTime()-t.getLong("At")+(double)partial,0,1);var dock=dockVisualR52(t,clock);if(dock!=null)return NervFootGuideDockR52.root(dock.view(),dock.turn());var timeline=t.getCompound("RideTimelineR52");return !timeline.isEmpty()&&timeline.getLong("At")==t.getLong("At")?NervLegacyCarrierRideR52.rootAtR52(timeline,clock):decode(t.getCompound("Previous")).interpolate(current,clock);}
 private static EvaUnit01Entity continuousEvaR52(NervCarrierPlatformEntity e){var t=e.originalCarrierStateR52();if(!e.level().isClientSide||!t.getBoolean("Attached")||!t.hasUUID("OriginalEva"))return null;for(var eva:e.level().getEntitiesOfClass(EvaUnit01Entity.class,e.getBoundingBox().inflate(128),v->v.getUUID().equals(t.getUUID("OriginalEva"))))if(EvaMechanicalFrameR52.continuousWindowR52(eva))return eva;return null;}
 public static Vec3 uprightDirectionR52(NervCarrierPlatformEntity e,float partial){var eva=continuousEvaR52(e);if(eva!=null)return EvaMechanicalFrameR52.continuousWindowTangentR52(eva,partial);var t=e.originalCarrierStateR52();return t.contains("OuterDirectionR52")?decode(t.getCompound("OuterDirectionR52")).translation():actualRoot(e,1).transformVector(new Vec3(0,0,1));}
 public static Vec3 guideUp(NervCarrierPlatformEntity e){var t=e.originalCarrierStateR52();return t.contains("GuideUp")?decode(t.getCompound("GuideUp")).translation():new Vec3(0,1,0);}
 public static Vec3 guideUp(NervCarrierPlatformEntity e,float partial){var current=guideUp(e);var t=e.originalCarrierStateR52();if(!e.level().isClientSide||!t.contains("PreviousGuideUp"))return current;var before=decode(t.getCompound("PreviousGuideUp")).translation();float blend=(float)net.minecraft.util.Mth.clamp(e.level().getGameTime()-t.getLong("At")+(double)partial,0,1);var dock=dockVisualR52(t,blend);if(dock!=null)return NervFootGuideDockR52.guideUpR52(dock.view(),dock.turn());var turn=new org.joml.Quaternionf().rotationTo(before.toVector3f(),current.toVector3f());return new Vec3(new org.joml.Quaternionf().slerp(turn,blend).transform(before.toVector3f())).normalize();}
 public static NervLegacyCarrierRideR52.RidePose actualRidePoseR52(NervCarrierPlatformEntity e){if(!declared(e))throw new IllegalStateException("Actual original carrier required");return NervLegacyCarrierRideR52.decode(e.originalCarrierStateR52().getCompound("RidePoseR52"));}
 public static NervLegacyCarrierRideR52.RidePose actualRidePoseR52(NervCarrierPlatformEntity e,float partial){var t=e.originalCarrierStateR52();var current=actualRidePoseR52(e);if(!e.level().isClientSide)return current;var eva=continuousEvaR52(e);double blend=eva!=null?EvaMechanicalFrameR52.continuousWindowFractionR52(eva,partial):net.minecraft.util.Mth.clamp(e.level().getGameTime()-t.getLong("At")+(double)partial,0,1);var timeline=t.getCompound("RideTimelineR52");return !timeline.isEmpty()&&timeline.getLong("At")==t.getLong("At")?NervLegacyCarrierRideR52.poseAtR52(timeline,blend):NervLegacyCarrierRideR52.interpolate(NervLegacyCarrierRideR52.decode(t.getCompound("PreviousRidePoseR52")),current,blend);}
 /** A source-checked slide/hinge step updates the same hardware clock. The
  * caller separately retains its physical RAIL/SPACE lease. */
 public static boolean acceptRideStepR52(ServerLevel l,NervLegacyCarrierRideR52.AcceptedRideStep proof){if(proof==null||!proof.current(l)||proof.checkedAt()!=l.getGameTime()||!(l.getEntity(proof.actor()) instanceof NervCarrierPlatformEntity e)||!actualRidePoseR52(e).equals(proof.fromPose()))return false;var tag=moved(e,proof.toRoot(),progress(e,1),guideUp(e));tag.put("PreviousRidePoseR52",NervLegacyCarrierRideR52.encode(proof.fromPose()));tag.put("RidePoseR52",NervLegacyCarrierRideR52.encode(proof.toPose()));tag.put("RideTimelineR52",proof.timelineState());e.acceptOriginalCarrierStateR52(new DeclaredState(e,tag));var p=proof.toRoot().translation();e.moveControlled(p.x,p.y,p.z);try{e.setBoundingBox(boundsR52(e));}catch(IOException missing){throw new IllegalStateException("Accepted real running shoe source unavailable",missing);}return true;}
 public static boolean attachedTo(NervCarrierPlatformEntity n,EvaUnit01Entity e){var t=n.originalCarrierStateR52();return declared(n)&&t.getBoolean("Attached")&&t.getUUID("OriginalEva").equals(e.getUUID());}
 /** Only this actual carried hardware may be omitted as a duplicate of the
  * captured assembly surface. Other carriers remain physical obstacles. */
 public static boolean isCapturedMemberR52(EvaUnit01Entity eva,Entity actor){if(!(actor instanceof NervCarrierPlatformEntity n)||!EvaMechanicalFrameR52.active(eva)||!attachedTo(n,eva)||!n.getUUID().equals(entityUUID(eva))||progress(n,1)!=1||n.originalCarrierStateR52().getLong("Epoch")!=EvaMechanicalFrameR52.epoch(eva))return false;return NervAirTransportManifestR52.same(actualRoot(n,1),EvaMechanicalFrameR52.frame(eva,1));}
 public static boolean setAttachedR52(ServerLevel l,NervCarrierPlatformEntity n,EvaUnit01Entity eva,boolean attached)throws IOException {if(!declared(n)||!n.originalCarrierStateR52().getUUID("OriginalEva").equals(eva.getUUID()))return false;if(attached){if(!EvaMechanicalFrameR52.active(eva)||!NervAirTransportManifestR52.same(actualRoot(n,1),EvaMechanicalFrameR52.frame(eva,1))||!carrierFootBearingR52(l,n,eva,EvaMechanicalFrameR52.capturedGeometry(eva),EvaMechanicalFrameR52.frame(eva,1)))return false;}else if(!attachedTo(n,eva))return true;var tag=n.originalCarrierStateR52();tag.putBoolean("Attached",attached);n.acceptOriginalCarrierStateR52(new DeclaredState(n,tag));return true;}
 private static synchronized Map<String,NervRigidMeshSweepR52> base(int variant)throws IOException {NervOuterCarrierGuideR52.install();var known=BASE.get(variant);if(known!=null)return known;byte[] receipt=EvaOriginalMeshGeometryR52.classpathBytes("eva/full_assembly_geometry_r52_sources.json");try{if(!HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(receipt)).equals(SOURCE_SHA))throw new IllegalStateException("Original full carrier selection changed");}catch(java.security.NoSuchAlgorithmException impossible){throw new IllegalStateException(impossible);}var result=new LinkedHashMap<String,NervRigidMeshSweepR52>();FullAssemblyGeometryR52.installClasspath();NervMappedPlugMechanicsR52.install();NervMappedPlugMechanicsR52.selectedMachinery().carrierParts(variant,1,false,0,64).forEach((name,xyz)->result.put(name,new NervRigidMeshSweepR52(xyz)));known=Collections.unmodifiableMap(result);BASE.put(variant,known);return known;}
 public static List<Part> partsAtR52(int variant,RigidTransform root,float rise,Vec3 up)throws IOException {return partsAtR52(variant,root,rise,up,NervLegacyCarrierRideR52.rest());}
 public static List<Part> partsAtR52(int variant,RigidTransform root,float rise,Vec3 up,NervLegacyCarrierRideR52.RidePose ride)throws IOException {return partsAtR52(variant,root,rise,up,ride,root.transformVector(new Vec3(0,0,1)));}
 public static List<Part> partsAtR52(int variant,RigidTransform root,float rise,Vec3 up,NervLegacyCarrierRideR52.RidePose ride,Vec3 direction)throws IOException {if(!Float.isFinite(rise)||rise<0||rise>1)throw new IllegalArgumentException("Actual bounded original actuator required");var raised=root.compose(new RigidTransform(new Vec3(0,-64D*(1-rise),0),0,0,0,1));var out=new ArrayList<Part>();for(var p:base(variant).entrySet())out.add(new Part(p.getKey(),p.getKey().startsWith("sole_bearing_")?Role.SOLE_BEARING:Role.STRUCTURE,p.getValue(),raised));for(var p:NervOuterCarrierGuideR52.partsAt(root,rise,direction))out.add(new Part(p.name(),Role.RUNNING_BOGIE,p.mesh(),p.frame()));for(var p:NervLegacyCarrierRideR52.partsAtR52(variant,root,rise,new NervLegacyCarrierRideR52.RidePose(ride.joints(),false)))out.add(new Part(p.name(),Role.RUNNING_BOGIE,p.mesh(),p.frame()));return List.copyOf(out);}
 public static List<Part> actualPartsR52(NervCarrierPlatformEntity e)throws IOException {return partsAtR52(e.getUnitVariant(),actualRoot(e,1),progress(e,1),guideUp(e),actualRidePoseR52(e),uprightDirectionR52(e,1));}
 public static List<NervFlightProofR52.ObstacleMesh> actualMeshesR52(NervCarrierPlatformEntity e)throws IOException {var out=new ArrayList<NervFlightProofR52.ObstacleMesh>();for(var p:actualPartsR52(e))out.add(new NervFlightProofR52.ObstacleMesh(p.mesh(),p.frame()));return List.copyOf(out);}
 public static AABB raisedBoundsAtR52(int variant,RigidTransform root)throws IOException {AABB b=null;for(var p:partsAtR52(variant,root,1,new Vec3(0,1,0))){var box=p.mesh().envelope(p.frame(),p.frame());b=b==null?box:b.minmax(box);}return b;}
 public static AABB boundsR52(NervCarrierPlatformEntity e)throws IOException {AABB b=null;for(var p:actualPartsR52(e)){var box=p.mesh().envelope(p.frame(),p.frame());b=b==null?box:b.minmax(box);}return b;}
 public static boolean carrierFootBearingR52(ServerLevel l,NervCarrierPlatformEntity carrier,EvaUnit01Entity eva,EvaOriginalMeshGeometryR52.Geometry body,RigidTransform root)throws IOException {if(!declared(carrier)||progress(carrier,1)!=1||carrier.getUnitVariant()!=eva.getUnitVariant())return false;var local=actualRoot(carrier,1).inverse().compose(root);var transformed=new LinkedHashMap<String,double[]>();for(var p:body.parts()){var xyz=p.triangles();for(int i=0;i<xyz.length;i+=3){var q=local.transformPoint(new Vec3(xyz[i],xyz[i+1],xyz[i+2]));xyz[i]=q.x;xyz[i+1]=q.y;xyz[i+2]=q.z;}transformed.put(p.bone()+"/"+transformed.size(),xyz);}for(String bone:List.of("foot_l","foot_r")){var points=new ArrayList<Vec3>();for(var p:body.parts())if(p.bone().equals(bone)){double low=p.bounds().minY;for(var vertex:p.vertices())if(vertex.y<=low+.002)points.add(local.transformPoint(vertex));}boolean finite=false;for(var p:points){double h=Double.NEGATIVE_INFINITY;for(var shoe:base(eva.getUnitVariant()).entrySet())if(shoe.getKey().startsWith("sole_bearing_"))h=Math.max(h,NervMappedPlugMechanicsR52.surfaceHeight(shoe.getValue().triangles(),p.x,p.z));if(!Double.isFinite(h)||Math.abs(h-p.y)>.002)return false;}for(int a=0;a<points.size()&&!finite;a++)for(int b=a+1;b<points.size()&&!finite;b++)for(int c=b+1;c<points.size();c++){var x=points.get(a);var y=points.get(b);var z=points.get(c);if(Math.abs((y.x-x.x)*(z.z-x.z)-(z.x-x.x)*(y.z-x.z))>.0025){finite=true;break;}}if(!finite)return false;}return true;}
 public static final class DeclaredState {
  private final UUID actor;private final long at;private final CompoundTag previous,next;
  private DeclaredState(NervCarrierPlatformEntity e,CompoundTag next){actor=e.getUUID();at=e.level().getGameTime();previous=e.originalCarrierStateR52();this.next=next.copy();}
  public boolean current(NervCarrierPlatformEntity e){return !e.level().isClientSide&&e.getUUID().equals(actor)&&e.level().getGameTime()==at&&e.originalCarrierStateR52().equals(previous);}
  public CompoundTag next(){return next.copy();}
 }
 public static boolean declareNewR52(NervCarrierPlatformEntity e,Original o,RigidTransform originalRoot,float actualRise){if(e.level().isClientSide||e.getUnitVariant()!=o.variant()||!e.getUUID().equals(proposedIdentityR52(o.epoch(),o.eva()))||!e.originalCarrierStateR52().isEmpty()||!e.hasDeclaredMachineFrameR52()||actualRise<0||actualRise>1)return false;var tag=new CompoundTag();tag.putString("Source",SOURCE_SHA);tag.putString("GuideSource",NervFootGuideRigR52.SOURCE_SHA);tag.putUUID("OriginalEva",o.eva());tag.putLong("Epoch",o.epoch());tag.putString("Directory",e.getPersistentData().getString("MachineDirectoryR52"));tag.put("Current",encode(originalRoot));tag.put("Previous",encode(originalRoot));tag.putFloat("Rise",actualRise);tag.putFloat("PreviousRise",actualRise);tag.putLong("At",e.level().getGameTime());tag.put("RidePoseR52",NervLegacyCarrierRideR52.encode(NervLegacyCarrierRideR52.rest()));tag.put("PreviousRidePoseR52",tag.getCompound("RidePoseR52").copy());tag.putBoolean("Attached",actualRise==1);e.acceptOriginalCarrierStateR52(new DeclaredState(e,tag));return declared(e);}
 public static boolean declareNewR52(NervCarrierPlatformEntity e,int variant,long epoch,UUID originalEva,RigidTransform originalRoot,float actualRise){if(e.level().isClientSide||e.getUnitVariant()!=variant||!e.getUUID().equals(proposedIdentityR52(epoch,originalEva))||!e.originalCarrierStateR52().isEmpty()||!e.hasDeclaredMachineFrameR52()||!Float.isFinite(actualRise)||actualRise<0||actualRise>1)return false;var tag=new CompoundTag();tag.putString("Source",SOURCE_SHA);tag.putString("GuideSource",NervFootGuideRigR52.SOURCE_SHA);tag.putUUID("OriginalEva",originalEva);tag.putLong("Epoch",epoch);tag.putString("Directory",e.getPersistentData().getString("MachineDirectoryR52"));tag.put("Current",encode(originalRoot));tag.put("Previous",encode(originalRoot));tag.putFloat("Rise",actualRise);tag.putFloat("PreviousRise",actualRise);tag.putLong("At",e.level().getGameTime());tag.put("RidePoseR52",NervLegacyCarrierRideR52.encode(NervLegacyCarrierRideR52.rest()));tag.put("PreviousRidePoseR52",tag.getCompound("RidePoseR52").copy());tag.putBoolean("Attached",false);e.acceptOriginalCarrierStateR52(new DeclaredState(e,tag));return declared(e);}
 public static final class CheckedStep {
  private final UUID actor;private final long at;private final CompoundTag before,after;private final List<AABB> envelopes;private final LeadMotionR52 lead;
  private CheckedStep(ServerLevel l,NervCarrierPlatformEntity e,CompoundTag after,List<AABB> boxes,LeadMotionR52 lead){actor=e.getUUID();at=l.getGameTime();before=e.originalCarrierStateR52();this.after=after.copy();envelopes=List.copyOf(boxes);this.lead=lead;}
  public UUID actor(){return actor;}public List<AABB> envelopes(){return envelopes;}
  public long checkedAt(){return at;}public RigidTransform fromRoot(){return decode(before.getCompound("Current"));}public RigidTransform toRoot(){return decode(after.getCompound("Current"));}public float fromRise(){return before.getFloat("Rise");}public float toRise(){return after.getFloat("Rise");}
  public boolean current(ServerLevel l){return l.getGameTime()==at&&l.getEntity(actor) instanceof NervCarrierPlatformEntity e&&declared(e)&&e.originalCarrierStateR52().equals(before)&&(lead==null||l.getEntity(lead.gantry()) instanceof NervCarrierPlatformEntity g&&g.serviceLeadStateR52().equals(lead.before()));}
  public boolean commit(ServerLevel l){if(lead!=null||!current(l))return false;return writeCarrierR52(l);}
  public boolean commit(ServerLevel l,NervLegacyCarrierRideR52.AcceptedLeadStep proof){if(lead==null)return proof==null&&commit(l);if(!current(l)||proof==null||!proof.current(l)||proof.checkedAt()!=at||!proof.carrier().equals(actor)||!proof.gantry().equals(lead.gantry())||!proof.fromSample().equals(lead.from())||!proof.toSample().equals(lead.to()))return false;if(!writeCarrierR52(l))return false;if(!acceptLeadStepR52(l,proof))throw new IllegalStateException("Prevalidated paired lead state changed during original carrier commit");return true;}
  private boolean writeCarrierR52(ServerLevel l){var e=(NervCarrierPlatformEntity)l.getEntity(actor);e.acceptOriginalCarrierStateR52(new DeclaredState(e,after));var root=actualRoot(e,1);e.moveControlled(root.translation().x,root.translation().y,root.translation().z);try{e.setBoundingBox(boundsR52(e));}catch(IOException unavailable){throw new IllegalStateException("Verified original carrier source vanished",unavailable);}return true;}
 }
 public static boolean acceptDockStepR52(ServerLevel l,NervFootGuideDockR52.AcceptedDockStep proof){if(proof==null||!proof.current(l)||!(l.getEntity(proof.actor()) instanceof NervCarrierPlatformEntity e)||!NervAirTransportManifestR52.same(actualRoot(e,1),proof.fromRoot())||guideUp(e).distanceTo(proof.fromUp())>1e-6||progress(e,1)!=1)return false;var after=moved(e,proof.toRoot(),1,proof.toUp());if(!NervFootGuideStationR52.acceptDockStepR52(l,proof))return false;var beforeDock=proof.stationState();beforeDock.putString("Stage",proof.from().stage().name());beforeDock.putDouble("Fraction",proof.from().fraction());beforeDock.put("Pose",NervFootGuideDockR52.encodePose(NervFootGuideDockR52.stationPose(proof.spec(),proof.from())));after.put("PreviousDockR52",beforeDock);after.put("DockR52",proof.stationState());e.acceptOriginalCarrierStateR52(new DeclaredState(e,after));var p=proof.toRoot().translation();e.moveControlled(p.x,p.y,p.z);try{e.setBoundingBox(boundsR52(e));}catch(IOException missing){throw new IllegalStateException("Accepted physical docking source unavailable",missing);}return true;}
 private static CompoundTag moved(NervCarrierPlatformEntity e,RigidTransform root,float rise,Vec3 up){var t=e.originalCarrierStateR52();t.remove("RideTimelineR52");var dock=t.getCompound("DockR52");if(dock.getString("Stage").equals("RELEASE")&&dock.getDouble("Fraction")==1&&!NervAirTransportManifestR52.same(actualRoot(e,1),root)){t.remove("DockR52");t.remove("PreviousDockR52");}t.put("Previous",t.getCompound("Current").copy());if(t.contains("RidePoseR52"))t.put("PreviousRidePoseR52",t.getCompound("RidePoseR52").copy());t.put("Current",encode(root));t.putFloat("PreviousRise",t.getFloat("Rise"));t.putFloat("Rise",rise);t.putLong("At",e.level().getGameTime());t.put("PreviousGuideUp",encode(new RigidTransform(guideUp(e),0,0,0,1)));t.put("GuideUp",encode(new RigidTransform(up,0,0,0,1)));return t;}
 private record LeadMotionR52(UUID gantry,CompoundTag before,NervLegacyCarrierRideR52.LeadSampleR52 from,NervLegacyCarrierRideR52.LeadSampleR52 to){}
